-- ============================================================================
--  BreakQ Admin Panel — database setup
--  Run this ONCE in the Supabase SQL editor of the app's project
--  (Dashboard -> SQL Editor -> New query -> paste all -> Run).
--
--  Safe to re-run. Resilient: if a table name differs in your schema, that
--  step is skipped with a notice instead of failing the whole script.
--
--  Creates:
--    1. is_admin()               helper used by every policy
--    2. admin_login_logs         login-attempt log (the only auth-layer gap)
--    3. shops.is_deleted         soft delete — never hard-delete a shop
--    4. shops.locality           proposed — area analytics (decision 1)
--    5. admin RLS policies       so the panel's reads/writes are allowed
--    6. admin_dashboard()        every analytics card in one call
--    7. admin_override_tier()    transactional manual tier change
-- ============================================================================


-- ── 1. admin check helper (must exist before any policy references it) ──────
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
      select 1 from public.profiles
          where id = auth.uid() and role = 'admin'
            );
            $$;

            grant execute on function public.is_admin() to authenticated;


            -- ── 2. login attempt log ──────────────────────────────────────────────────
            create table if not exists public.admin_login_logs (
              id         uuid primary key default gen_random_uuid(),
                admin_id   uuid references auth.users(id),
                  ip_address inet,
                    success    boolean not null,
                      created_at timestamptz not null default now()
                      );

                      alter table public.admin_login_logs enable row level security;

                      drop policy if exists "login log insert self" on public.admin_login_logs;
                      create policy "login log insert self" on public.admin_login_logs
                        for insert to authenticated
                          with check (admin_id = auth.uid() or admin_id is null);

                          drop policy if exists "login log admin read" on public.admin_login_logs;
                          create policy "login log admin read" on public.admin_login_logs
                            for select to authenticated
                              using (public.is_admin());


                              -- ── 3 + 4. schema additions on shops ─────────────────────────────────────
                              do $$
                              begin
                                alter table public.shops add column if not exists is_deleted boolean not null default false;
                                  alter table public.shops add column if not exists locality   text;
                                  exception when undefined_table then
                                    raise notice 'shops table not found — skipped is_deleted / locality';
                                    end $$;


                                    -- ── 5. admin RLS policies (additive — do not touch vendor/customer rules) ──
                                    do $$
                                    declare t text;
                                    begin
                                      -- full read + write for admins
                                        foreach t in array array[
                                            'shops','subscription_tiers','vendor_subscriptions','subscription_payments',
                                                'promo_codes','categories','promoted_placements'
                                                  ]
                                                    loop
                                                        begin
                                                              execute format('alter table public.%I enable row level security', t);
                                                                    execute format('drop policy if exists "admin manage %1$s" on public.%1$I', t);
                                                                          execute format(
                                                                                  'create policy "admin manage %1$s" on public.%1$I for all to authenticated '
                                                                                          || 'using (public.is_admin()) with check (public.is_admin())', t);
                                                                                              exception when undefined_table then
                                                                                                    raise notice 'skipped %: table not found', t;
                                                                                                        end;
                                                                                                          end loop;

                                                                                                            -- read-only for admins
                                                                                                              foreach t in array array['orders','order_items','products','shop_view_events','profiles']
                                                                                                                loop
                                                                                                                    begin
                                                                                                                          execute format('alter table public.%I enable row level security', t);
                                                                                                                                execute format('drop policy if exists "admin read %1$s" on public.%1$I', t);
                                                                                                                                      execute format(
                                                                                                                                              'create policy "admin read %1$s" on public.%1$I for select to authenticated '
                                                                                                                                                      || 'using (public.is_admin())', t);
                                                                                                                                                          exception when undefined_table then
                                                                                                                                                                raise notice 'skipped %: table not found', t;
                                                                                                                                                                    end;
                                                                                                                                                                      end loop;
                                                                                                                                                                      end $$;

                                                                                                                                                                      -- Let a signed-in user read + edit THEIR OWN profile (needed by the panel's
                                                                                                                                                                      -- "Edit profile"). Role changes by non-admins are reverted by the trigger below.
                                                                                                                                                                      drop policy if exists "read own profile" on public.profiles;
                                                                                                                                                                      create policy "read own profile" on public.profiles
                                                                                                                                                                        for select to authenticated using (id = auth.uid());

                                                                                                                                                                        drop policy if exists "update own profile" on public.profiles;
                                                                                                                                                                        create policy "update own profile" on public.profiles
                                                                                                                                                                          for update to authenticated
                                                                                                                                                                            using (id = auth.uid()) with check (id = auth.uid());

                                                                                                                                                                            -- Note: admins get READ on all profiles from the loop above (Users tab is
                                                                                                                                                                            -- view-only). There is deliberately no admin write/delete policy on profiles.

                                                                                                                                                                            -- Guard against privilege escalation: a non-admin cannot change their own role.
                                                                                                                                                                            create or replace function public.prevent_role_escalation()
                                                                                                                                                                            returns trigger
                                                                                                                                                                            language plpgsql
                                                                                                                                                                            security definer
                                                                                                                                                                            set search_path = public
                                                                                                                                                                            as $$
                                                                                                                                                                            begin
                                                                                                                                                                              if new.role is distinct from old.role and not public.is_admin() then
                                                                                                                                                                                  new.role := old.role;
                                                                                                                                                                                    end if;
                                                                                                                                                                                      return new;
                                                                                                                                                                                      end;
                                                                                                                                                                                      $$;

                                                                                                                                                                                      drop trigger if exists prevent_role_escalation on public.profiles;
                                                                                                                                                                                      create trigger prevent_role_escalation
                                                                                                                                                                                        before update on public.profiles
                                                                                                                                                                                          for each row execute function public.prevent_role_escalation();


                                                                                                                                                                                          -- ── 6. analytics dashboard (one round-trip) ───────────────────────────────
                                                                                                                                                                                          -- Each card is wrapped in its own exception block: a column-name mismatch
                                                                                                                                                                                          -- only nulls that one card, the rest still load.
                                                                                                                                                                                          create or replace function public.admin_dashboard()
                                                                                                                                                                                          returns jsonb
                                                                                                                                                                                          language plpgsql
                                                                                                                                                                                          security definer
                                                                                                                                                                                          set search_path = public
                                                                                                                                                                                          as $$
                                                                                                                                                                                          declare
                                                                                                                                                                                            v_role       text;
                                                                                                                                                                                              r            jsonb := '{}'::jsonb;
                                                                                                                                                                                                v            jsonb;
                                                                                                                                                                                                  n            timestamptz := now();
                                                                                                                                                                                                    has_locality boolean;
                                                                                                                                                                                                    begin
                                                                                                                                                                                                      select role into v_role from public.profiles where id = auth.uid();
                                                                                                                                                                                                        if v_role is distinct from 'admin' then
                                                                                                                                                                                                            raise exception 'admin_dashboard: caller is not an admin';
                                                                                                                                                                                                              end if;

                                                                                                                                                                                                                begin r := r || jsonb_build_object('orders_24h',
                                                                                                                                                                                                                    (select count(*) from public.orders where created_at > n - interval '24 hours'));
                                                                                                                                                                                                                      exception when others then r := r || jsonb_build_object('orders_24h', null); end;

                                                                                                                                                                                                                        begin r := r || jsonb_build_object('orders_30d',
                                                                                                                                                                                                                            (select count(*) from public.orders where created_at > n - interval '30 days'));
                                                                                                                                                                                                                              exception when others then r := r || jsonb_build_object('orders_30d', null); end;

                                                                                                                                                                                                                                begin r := r || jsonb_build_object('orders_prev_30d',
                                                                                                                                                                                                                                    (select count(*) from public.orders
                                                                                                                                                                                                                                         where created_at > n - interval '60 days' and created_at <= n - interval '30 days'));
                                                                                                                                                                                                                                           exception when others then r := r || jsonb_build_object('orders_prev_30d', null); end;

                                                                                                                                                                                                                                             begin r := r || jsonb_build_object('platform_revenue_today',
                                                                                                                                                                                                                                                 (select coalesce(sum(coalesce(commission_rupees,0) + coalesce(platform_fee_rupees,0)),0)
                                                                                                                                                                                                                                                      from public.orders where created_at::date = n::date));
                                                                                                                                                                                                                                                        exception when others then r := r || jsonb_build_object('platform_revenue_today', null); end;

                                                                                                                                                                                                                                                          begin r := r || jsonb_build_object('platform_revenue_7d',
                                                                                                                                                                                                                                                              (select coalesce(sum(coalesce(commission_rupees,0) + coalesce(platform_fee_rupees,0)),0)
                                                                                                                                                                                                                                                                   from public.orders where created_at > n - interval '7 days'));
                                                                                                                                                                                                                                                                     exception when others then r := r || jsonb_build_object('platform_revenue_7d', null); end;

                                                                                                                                                                                                                                                                       begin r := r || jsonb_build_object('platform_revenue_30d',
                                                                                                                                                                                                                                                                           (select coalesce(sum(coalesce(commission_rupees,0) + coalesce(platform_fee_rupees,0)),0)
                                                                                                                                                                                                                                                                                from public.orders where created_at > n - interval '30 days'));
                                                                                                                                                                                                                                                                                  exception when others then r := r || jsonb_build_object('platform_revenue_30d', null); end;

                                                                                                                                                                                                                                                                                    begin r := r || jsonb_build_object('commission_30d',
                                                                                                                                                                                                                                                                                        (select coalesce(sum(commission_rupees),0) from public.orders where created_at > n - interval '30 days'));
                                                                                                                                                                                                                                                                                          exception when others then r := r || jsonb_build_object('commission_30d', null); end;

                                                                                                                                                                                                                                                                                            begin r := r || jsonb_build_object('platform_fee_30d',
                                                                                                                                                                                                                                                                                                (select coalesce(sum(platform_fee_rupees),0) from public.orders where created_at > n - interval '30 days'));
                                                                                                                                                                                                                                                                                                  exception when others then r := r || jsonb_build_object('platform_fee_30d', null); end;

                                                                                                                                                                                                                                                                                                    begin r := r || jsonb_build_object('shops_total', (select count(*) from public.shops));
                                                                                                                                                                                                                                                                                                      exception when others then r := r || jsonb_build_object('shops_total', null); end;

                                                                                                                                                                                                                                                                                                        begin r := r || jsonb_build_object('shops_pending',
                                                                                                                                                                                                                                                                                                            (select count(*) from public.shops where status = 'pending'));
                                                                                                                                                                                                                                                                                                              exception when others then r := r || jsonb_build_object('shops_pending', null); end;

                                                                                                                                                                                                                                                                                                                begin r := r || jsonb_build_object('users_total', (select count(*) from public.profiles));
                                                                                                                                                                                                                                                                                                                  exception when others then r := r || jsonb_build_object('users_total', null); end;

                                                                                                                                                                                                                                                                                                                    begin r := r || jsonb_build_object('users_before_window',
                                                                                                                                                                                                                                                                                                                        (select count(*) from public.profiles where created_at <= n - interval '180 days'));
                                                                                                                                                                                                                                                                                                                          exception when others then r := r || jsonb_build_object('users_before_window', 0); end;

                                                                                                                                                                                                                                                                                                                            begin r := r || jsonb_build_object('user_signups', (
                                                                                                                                                                                                                                                                                                                                select coalesce(jsonb_agg(jsonb_build_object('d', d, 'count', c) order by d), '[]'::jsonb) from (
                                                                                                                                                                                                                                                                                                                                      select date_trunc('day', created_at)::date d, count(*) c
                                                                                                                                                                                                                                                                                                                                            from public.profiles
                                                                                                                                                                                                                                                                                                                                                  where created_at > n - interval '180 days'
                                                                                                                                                                                                                                                                                                                                                        group by 1) t));
                                                                                                                                                                                                                                                                                                                                                          exception when others then r := r || jsonb_build_object('user_signups', '[]'::jsonb); end;

                                                                                                                                                                                                                                                                                                                                                            begin r := r || jsonb_build_object('busy_hour', (
                                                                                                                                                                                                                                                                                                                                                                select jsonb_build_object('hour', h, 'orders', c) from (
                                                                                                                                                                                                                                                                                                                                                                      select extract(hour from created_at)::int h, count(*) c
                                                                                                                                                                                                                                                                                                                                                                            from public.orders group by 1 order by 2 desc limit 1) t));
                                                                                                                                                                                                                                                                                                                                                                              exception when others then r := r || jsonb_build_object('busy_hour', null); end;

                                                                                                                                                                                                                                                                                                                                                                                begin r := r || jsonb_build_object('top_product', (
                                                                                                                                                                                                                                                                                                                                                                                    select jsonb_build_object('name', coalesce(p.name,'Unknown product'), 'units', s.units) from (
                                                                                                                                                                                                                                                                                                                                                                                          select product_id, sum(quantity)::numeric units
                                                                                                                                                                                                                                                                                                                                                                                                from public.order_items group by product_id order by units desc limit 1) s
                                                                                                                                                                                                                                                                                                                                                                                                    left join public.products p on p.id = s.product_id));
                                                                                                                                                                                                                                                                                                                                                                                                      exception when others then r := r || jsonb_build_object('top_product', null); end;

                                                                                                                                                                                                                                                                                                                                                                                                        begin r := r || jsonb_build_object('top_category', (
                                                                                                                                                                                                                                                                                                                                                                                                            select jsonb_build_object('name', coalesce(c.name,'Unknown category'), 'revenue', s.rev) from (
                                                                                                                                                                                                                                                                                                                                                                                                                  select p.category_id, sum(oi.quantity * oi.unit_price)::numeric rev
                                                                                                                                                                                                                                                                                                                                                                                                                        from public.order_items oi join public.products p on p.id = oi.product_id
                                                                                                                                                                                                                                                                                                                                                                                                                              group by p.category_id order by rev desc limit 1) s
                                                                                                                                                                                                                                                                                                                                                                                                                                  left join public.categories c on c.id = s.category_id));
                                                                                                                                                                                                                                                                                                                                                                                                                                    exception when others then r := r || jsonb_build_object('top_category', null); end;

                                                                                                                                                                                                                                                                                                                                                                                                                                      begin r := r || jsonb_build_object('top_rated_shops', (
                                                                                                                                                                                                                                                                                                                                                                                                                                          select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from (
                                                                                                                                                                                                                                                                                                                                                                                                                                                select name, avg_rating, rating_count from public.shops
                                                                                                                                                                                                                                                                                                                                                                                                                                                      where rating_count > 0 order by avg_rating desc nulls last, rating_count desc limit 5) t));
                                                                                                                                                                                                                                                                                                                                                                                                                                                        exception when others then r := r || jsonb_build_object('top_rated_shops', '[]'::jsonb); end;

                                                                                                                                                                                                                                                                                                                                                                                                                                                          begin r := r || jsonb_build_object('most_searched_product', (
                                                                                                                                                                                                                                                                                                                                                                                                                                                              select jsonb_build_object('term', search_term, 'hits', c) from (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    select search_term, count(*) c from public.shop_view_events
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          where event_type = 'search' and coalesce(search_term,'') <> ''
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                group by search_term order by c desc limit 1) t));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  exception when others then r := r || jsonb_build_object('most_searched_product', null); end;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    begin r := r || jsonb_build_object('most_searched_category', (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        select jsonb_build_object('name', name, 'hits', c) from (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              select cc.name, count(*) c
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    from public.shop_view_events sve
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          join public.products pp on pp.id = sve.product_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                join public.categories cc on cc.id = pp.category_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      where sve.event_type = 'search' and sve.product_id is not null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            group by cc.name order by c desc limit 1) t));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              exception when others then r := r || jsonb_build_object('most_searched_category', null); end;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                begin r := r || jsonb_build_object('daily_series', (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    select coalesce(jsonb_agg(to_jsonb(t) order by t.d), '[]'::jsonb) from (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          select date_trunc('day', created_at)::date d,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       count(*) orders,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    coalesce(sum(total_amount),0) revenue,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 coalesce(sum(coalesce(commission_rupees,0) + coalesce(platform_fee_rupees,0)),0) platform_revenue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       from public.orders
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             where created_at > n - interval '30 days'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   group by 1) t));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     exception when others then r := r || jsonb_build_object('daily_series', '[]'::jsonb); end;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       begin r := r || jsonb_build_object('daily_series_prev', (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           select coalesce(jsonb_agg(to_jsonb(t) order by t.d), '[]'::jsonb) from (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 select date_trunc('day', created_at)::date d,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              count(*) orders,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           coalesce(sum(total_amount),0) revenue,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        coalesce(sum(coalesce(commission_rupees,0) + coalesce(platform_fee_rupees,0)),0) platform_revenue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              from public.orders
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    where created_at > n - interval '60 days' and created_at <= n - interval '30 days'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          group by 1) t));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            exception when others then r := r || jsonb_build_object('daily_series_prev', '[]'::jsonb); end;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              begin r := r || jsonb_build_object('hourly', (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  select coalesce(jsonb_agg(jsonb_build_object('hour', h, 'orders', c) order by h), '[]'::jsonb) from (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        select gs.h, count(o.*) c
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              from generate_series(0, 23) gs(h)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    left join public.orders o
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            on extract(hour from o.created_at)::int = gs.h
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   and o.created_at > n - interval '30 days'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         group by gs.h) t));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           exception when others then r := r || jsonb_build_object('hourly', '[]'::jsonb); end;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             -- Top Performing Area — only if shops.locality exists (decision 1).
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               select exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   select 1 from information_schema.columns
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       where table_schema = 'public' and table_name = 'shops' and column_name = 'locality'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ) into has_locality;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if has_locality then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     execute $q$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             select jsonb_build_object('locality', locality, 'orders', c) from (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       select sh.locality, count(*) c
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 from public.orders o join public.shops sh on sh.id = o.shop_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           where sh.locality is not null and sh.locality <> ''
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     group by sh.locality order by c desc limit 1) t
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           $q$ into v;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 r := r || jsonb_build_object('top_area', v);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     exception when others then r := r || jsonb_build_object('top_area', null); end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           r := r || jsonb_build_object('top_area', null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               return r || jsonb_build_object('generated_at', n, 'has_locality', has_locality);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               grant execute on function public.admin_dashboard() to authenticated;


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               -- ── 7. manual tier change (single transaction) ────────────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               --   NOTE: if subscription_tiers.id is not uuid in your schema, change the
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               --   p_tier_id argument type below to match.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               create or replace function public.admin_override_tier(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 p_shop_id        text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   p_tier_id        uuid,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     p_commission_pct numeric,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       p_amount         numeric
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       returns void
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       language plpgsql
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       security definer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       set search_path = public
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       as $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if not public.is_admin() then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             raise exception 'admin_override_tier: not authorized';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 update public.vendor_subscriptions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      set status = 'expired', expires_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         where shop_id = p_shop_id and status = 'active';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           insert into public.vendor_subscriptions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               (shop_id, tier_id, status, started_at,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    commission_locked_at_percent, amount_paid_rupees, payment_ref)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      values
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (p_shop_id, p_tier_id, 'active', now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               p_commission_pct, p_amount, 'manual-admin-override');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $$;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               grant execute on function public.admin_override_tier(text, uuid, numeric, numeric) to authenticated;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               